import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import type { AddressInfo } from 'node:net';
import { toNodeHandler } from '@modelcontextprotocol/node';
import { FastMCP, type Logger } from '@prefecthq/fastmcp-ts/server';
import { LineMcpError } from '../errors.ts';
import { lockPort } from '../lock.ts';
import { Outbox } from '../outbox.ts';
import { Invocations, type ToolContext, registerTool } from './tool.ts';
import * as archiveTools from './tools/archive.ts';
import { QueryRunner, query } from './tools/query.ts';
import { react } from './tools/react.ts';
import { sendMessage } from './tools/send.ts';
import { unsend } from './tools/unsend.ts';
import * as upstreamTools from './tools/upstream.ts';

/** Default MCP port; the lock port (47821) is a different one. */
export const defaultMcpPort = 47822;
export const mcpPath = '/mcp';

export function mcpPort(env: NodeJS.ProcessEnv = process.env): number {
	const raw = env.LINE_MCP_PORT;
	const port = raw ? Number(raw) : defaultMcpPort;
	if (!Number.isInteger(port) || port < 1 || port > 65535) {
		throw new Error('LINE_MCP_PORT must be a TCP port number');
	}
	if (port === lockPort(env)) {
		throw new Error('LINE_MCP_PORT must differ from the lock port');
	}
	return port;
}

export const readTools = [
	archiveTools.status,
	query,
	upstreamTools.getAttachment,
	upstreamTools.getAnnouncements,
	upstreamTools.getProfile
];

/** Tools that act on LINE, each through the outbox. */
export const mutatingTools = [sendMessage, react, unsend];

export interface McpServer {
	readonly port: number;
	readonly url: string;
	/**
	 * Stops listening, drops open connections, cancels every tool call and
	 * resolves once the port is free, every call has settled and the query
	 * runner has exited.
	 */
	close(): Promise<void>;
}

/** Framework diagnostics reach the daemon log as fixed text only, never with their metadata. */
function frameworkLogger(context: ToolContext): Logger {
	const forward = (level: string) => (message: string) =>
		context.log({ event: 'mcp_framework', level, message: message.slice(0, 200) });
	return { debug: () => {}, info: () => {}, warn: forward('warn'), error: forward('error') };
}

function refuse(res: ServerResponse, status: number, message: string): void {
	res
		.writeHead(status, { 'content-type': 'application/json', connection: 'close' })
		.end(JSON.stringify({ jsonrpc: '2.0', error: { code: -32000, message }, id: null }));
}

/**
 * Serves the tools over Streamable HTTP on `127.0.0.1:<port>/mcp`. Opening the
 * outbox here is the startup step that turns an `in_flight` action left by a
 * stopped daemon into `unknown`.
 *
 * Prefect's own listener (`run()`) answers CORS preflights and attaches
 * `Access-Control-Allow-Origin: *` unless told otherwise, and its DNS-rebinding
 * guard accepts any localhost origin on any port
 * (`src/server/FastMCP.ts:2272-2300`, `docs/servers/running.mdx`). So this
 * listener is our own: it serves Prefect's stateless `fetch()` entry, which
 * keeps no session between requests and adds no CORS headers, behind checks
 * that run before any body is read. A request carrying an `Origin` header
 * (every browser request; native clients send none) or a `Host` other than
 * this exact listener is refused.
 */
export async function startMcpServer(
	context: ToolContext,
	options: { port?: number } = {}
): Promise<McpServer> {
	const mcp = new FastMCP({
		name: 'line-mcp',
		version: '0.0.0',
		http: { cors: false },
		logger: frameworkLogger(context),
		logLevel: 'warn'
	});
	const invocations = new Invocations();
	const served = {
		...context,
		outbox: new Outbox(context.db, { log: context.log }),
		// Started on the first query; `close` ends it.
		queries: new QueryRunner({
			root: context.root,
			privacy: context.privacy,
			...(context.queryTimeoutMs ? { timeoutMs: context.queryTimeoutMs } : {})
		})
	};
	for (const tool of [...readTools, ...mutatingTools]) {
		registerTool(mcp, served, tool, invocations);
	}

	const handler = toNodeHandler(
		{ fetch: (request, init) => mcp.fetch(request, init) },
		{
			maxRequestBodySize: 1024 * 1024,
			onerror: () => context.log({ event: 'mcp_request_failed' })
		}
	);
	let allowedHosts: Set<string> = new Set();
	const server = createServer((req: IncomingMessage, res: ServerResponse) => {
		if (req.headers.origin !== undefined) return refuse(res, 403, 'Origin not allowed');
		if (!allowedHosts.has(req.headers.host ?? '')) return refuse(res, 403, 'Host not allowed');
		if ((req.url ?? '').split('?')[0] !== mcpPath) return refuse(res, 404, 'Not found');
		// A client that goes away before its answer cancels the tool call: queued
		// upstream work leaves the pool instead of dispatching for nobody.
		const request = new AbortController();
		res.once('close', () => {
			if (!res.writableFinished) {
				request.abort(new LineMcpError('cancelled', 'The client closed the request'));
			}
		});
		void invocations.serve(request.signal, () => handler(req, res));
	});
	// Idle keep-alive sockets go away soon; a dropped client cannot pin one.
	server.keepAliveTimeout = 5000;
	server.headersTimeout = 10_000;
	server.requestTimeout = 5 * 60 * 1000;
	server.on('clientError', (_error, socket) => socket.destroy());

	const port = options.port ?? mcpPort();
	try {
		await new Promise<void>((resolve, reject) => {
			server.once('error', reject);
			server.listen({ host: '127.0.0.1', port, exclusive: true }, () => {
				server.off('error', reject);
				resolve();
			});
		});
	} catch (error) {
		if ((error as NodeJS.ErrnoException).code === 'EADDRINUSE') {
			throw new LineMcpError('mcp_port_in_use', `Another process holds the MCP port ${port}`);
		}
		throw new LineMcpError('mcp_port_failed', `Could not bind the MCP port ${port}`, {
			cause: error
		});
	}
	server.on('error', () => {});
	const bound = (server.address() as AddressInfo).port;
	allowedHosts = new Set([`127.0.0.1:${bound}`, `localhost:${bound}`]);

	let closed: Promise<void> | undefined;
	return {
		port: bound,
		url: `http://127.0.0.1:${bound}${mcpPath}`,
		close: () =>
			(closed ??= (async () => {
				const done = new Promise<void>((resolve) => server.close(() => resolve()));
				server.closeAllConnections();
				const settled = invocations.close();
				await done;
				await settled;
				await served.queries.close();
				await mcp.close();
			})())
	};
}

import { AsyncLocalStorage } from 'node:async_hooks';
import type { DatabaseSync } from 'node:sqlite';
import type { BaseClient } from '@evex/linejs/base';
import { type FastMCP, ToolResult } from '@prefecthq/fastmcp-ts/server';
import { z } from 'zod';
import type { ArchiveStatus } from '../archive.ts';
import { LineMcpError, MappedFailure, mapError } from '../errors.ts';
import type { Outbox } from '../outbox.ts';
import type { StatePrivacy } from '../privacy.ts';
import { freshness } from '../queries.ts';
import type { Log } from '../session.ts';
import type { Pool } from '../sync/loop.ts';
import type { QueryRunner } from './tools/query.ts';

/** What the tools work with: the daemon's archive, session client and upstream pool. */
export interface ToolContext {
	db: DatabaseSync;
	/** The state root; the `query` tool's runner opens its archive read-only. */
	root: string;
	base: BaseClient;
	selfMid: string;
	/** The bounded pool history and media share (architecture, Upstream concurrency). */
	pool: Pool;
	/** Private directory that downloaded attachments go to. */
	attachments: string;
	/** Keeps `attachments` and every file returned from it private. */
	privacy: StatePrivacy;
	/** Largest attachment download in bytes; 100 MiB by default. */
	maxAttachmentBytes?: number;
	/** Time limit of one `query` in milliseconds; 5 s by default. */
	queryTimeoutMs?: number;
	/** Current health; cached reads report it in every result. */
	status(): ArchiveStatus;
	log: Log;
}

/** The context the served tools get: the caller's, plus the outbox and query runner of the server. */
export interface ServedContext extends ToolContext {
	outbox: Outbox;
	queries: QueryRunner;
}

export const service = z
	.enum(['talk', 'square'])
	.describe('talk: one-to-one chats, groups and rooms; square: OpenChat');
export const chatId = z.string().min(1).max(100).describe("The chat's chat_id from query");
export const messageId = z
	.string()
	.regex(/^\d{1,20}$/)
	.describe('LINE message ID (decimal string)');
export const idempotencyKey = z
	.string()
	.min(8)
	.max(200)
	.regex(/^[\x21-\x7e]+$/)
	.describe(
		'Unique key for this one intended action (for example a UUID), 8 to 200 printable ASCII characters. Reuse it only to retry the same action: a retry never acts twice. A new action needs a new key.'
	);

export interface ToolDefinition<S extends z.ZodObject> {
	name: string;
	description: string;
	input: S;
	/** True when the tool asks LINE rather than reading the archive. */
	upstream?: boolean;
	/** True when the tool acts on LINE (send, react, unsend) through the outbox. */
	mutating?: boolean;
	/**
	 * True when a failure's message may quote archive data (SQLite's
	 * diagnostics in `query`): the result keeps it, the log gets the code alone.
	 */
	quotesArchive?: boolean;
	/** `signal` aborts when the client goes away or the server shuts down. */
	run: (args: z.output<S>, context: ServedContext, signal: AbortSignal) => Promise<object> | object;
}

/**
 * The tool calls in progress and their cancellation. The HTTP listener owns
 * each request, so it scopes a signal over the request's handling that aborts
 * when the client closes the connection; `close` aborts every call at once.
 * Prefect does not end a running handler when a Streamable HTTP client goes
 * away (`CancellationMiddleware` in its server.d.ts), hence this own signal.
 */
export class Invocations {
	readonly #scope = new AsyncLocalStorage<AbortSignal>();
	readonly #shutdown = new AbortController();
	readonly #running = new Set<Promise<unknown>>();

	/** Runs the handling of one HTTP request under `signal`. */
	serve<T>(signal: AbortSignal, handle: () => T): T {
		return this.#scope.run(AbortSignal.any([signal, this.#shutdown.signal]), handle);
	}

	/** Runs one tool call and keeps track of it until it settles. */
	async run<T>(call: (signal: AbortSignal) => Promise<T>): Promise<T> {
		const signal = this.#scope.getStore() ?? this.#shutdown.signal;
		const task = call(signal);
		const settled = task.then(
			() => {},
			() => {}
		);
		this.#running.add(settled);
		void settled.then(() => this.#running.delete(settled));
		return await task;
	}

	/** Aborts every call and resolves once all of them have settled. */
	async close(): Promise<void> {
		this.#shutdown.abort(new LineMcpError('shutting_down', 'The server is shutting down'));
		await Promise.all(this.#running);
	}
}

export function defineTool<S extends z.ZodObject>(
	definition: ToolDefinition<S>
): ToolDefinition<S> {
	return definition;
}

/**
 * Registers a tool. Every result is an object envelope that reports the
 * archive's freshness. Every failure goes through the allowlisted mapper
 * (architecture, Errors): Prefect would otherwise return `err.message` as the
 * tool output, and LINEJS messages can carry response headers and body bytes.
 * A mutating tool's failure also reports its outbox state.
 */
export function registerTool<S extends z.ZodObject>(
	server: FastMCP,
	context: ServedContext,
	definition: ToolDefinition<S>,
	invocations: Invocations
): void {
	server.tool(
		{
			name: definition.name,
			description: definition.description,
			input: definition.input,
			// The idempotency key makes a repeated call with the same arguments act once.
			annotations: definition.mutating
				? { readOnlyHint: false, destructiveHint: true, idempotentHint: true, openWorldHint: true }
				: { readOnlyHint: true, openWorldHint: definition.upstream === true }
		},
		// Prefect validates the arguments with `input` before calling this.
		(args: Record<string, unknown>) =>
			invocations.run(async (signal) => {
				try {
					const result = await definition.run(args as z.output<S>, context, signal);
					return { ...freshness(context.status()), ...result };
				} catch (error) {
					const mapped = mapError(error, definition.name);
					context.log({
						event: 'tool_failed',
						...(definition.quotesArchive
							? { code: mapped.code, operation: mapped.operation }
							: mapped)
					});
					const details = error instanceof MappedFailure ? error.details : {};
					return new ToolResult({
						content: [{ type: 'text', text: JSON.stringify({ error: mapped, ...details }) }],
						isError: true
					});
				}
			})
	);
}

import { z } from 'zod';
import { listGaps } from '../../archive.ts';
import { readAccount } from '../../db.ts';
import { renderTime, timeZone } from '../../time.ts';
import { defineTool } from '../tool.ts';

// The archive's status, from the local copy alone; it never calls LINE. Agents
// read the archive itself with `query` (./query.ts).

export const status = defineTool({
	name: 'status',
	description:
		'Session health, last sync times, unreconciled coverage gaps, backfill progress, archive size and time_zone, the zone whose offset every time carries. Check stale before treating other results as current.',
	input: z.object({}),
	run: (_args, context) => {
		const { db } = context;
		const account = readAccount(db);
		const gaps = listGaps(db, { status: 'unreconciled' });
		const count = (sql: string) => Number(db.prepare(sql).get()?.count ?? 0);
		return {
			account: account ? { mid: account.mid, auth_state: account.authState } : null,
			unreconciled_gaps: gaps.length,
			gaps: gaps.slice(0, 50).map((gap) => ({
				service: gap.service,
				scope: gap.scope,
				reason: gap.reason,
				status: gap.status,
				opened_at: renderTime(gap.openedAt)
			})),
			backfill: context.status().backfill,
			archive: {
				chats: count('SELECT count(*) AS count FROM chat'),
				messages: count('SELECT count(*) AS count FROM message'),
				latest_seq: count('SELECT value AS count FROM change_counter WHERE id = 1')
			},
			time_zone: timeZone()
		};
	}
