// Tools that may ask LINE. Every request runs in the session's bounded pool
// and through its guards; failures reach the caller only through the mapper.

const mediaTypes = new Set(['IMAGE', 'VIDEO', 'AUDIO', 'FILE']);
/** Largest attachment `get_attachment` downloads; LINE's own file limit is far higher. */
export const maxAttachmentBytes = 100 * 1024 * 1024;

const integerId = (value: unknown): string | null => {
	try {
		return value === undefined || value === null ? null : decimal(value as string);
	} catch {
		return null;
	}
};

const text = (value: unknown): string | null =>
	typeof value === 'string' && value !== '' ? value : null;

function attachmentInfo(message: Message) {
	const metadata = message.contentMetadata ?? {};
	const size = Number(metadata.FILE_SIZE);
	const duration = Number(metadata.DURATION);
	return {
		file_name: text(metadata.FILE_NAME),
		file_size: Number.isSafeInteger(size) && size >= 0 ? size : null,
		duration_ms: Number.isSafeInteger(duration) && duration >= 0 ? duration : null,
		e2ee: Boolean(message.chunks?.length)
	};
}

/** The extension of `fileName` when it is plain, such as `.jpg`. */
function plainExtension(fileName: string | null | undefined): string | null {
	const extension = extname(fileName ?? '').toLowerCase();
	return /^\.[a-z0-9]{1,8}$/.test(extension) ? extension : null;
}

const ascii = (bytes: Uint8Array, start: number, end: number) =>
	Buffer.from(bytes.subarray(start, end)).toString('latin1');

/** ISO base media brands (`ftyp`) with an extension of their own; the rest are MP4. */
const brands: Record<string, string> = {
	'M4A ': '.m4a',
	'M4B ': '.m4a',
	'qt  ': '.mov',
	heic: '.heic',
	heix: '.heic',
	mif1: '.heic',
	avif: '.avif',
	'3gp4': '.3gp',
	'3gp5': '.3gp',
	'3gp6': '.3gp'
};

/** The extension the leading bytes of a file announce, for media LINE sends without a name. */
export function sniffExtension(head: Uint8Array): string | null {
	const [first, second] = head;
	if (first === 0xff && second === 0xd8 && head[2] === 0xff) return '.jpg';
	if (ascii(head, 0, 8) === '\x89PNG\r\n\x1a\n') return '.png';
	if (/^GIF8[79]a$/.test(ascii(head, 0, 6))) return '.gif';
	if (ascii(head, 0, 4) === 'RIFF') {
		const kind = ascii(head, 8, 12);
		if (kind === 'WEBP') return '.webp';
		if (kind === 'WAVE') return '.wav';
		if (kind === 'AVI ') return '.avi';
	}
	if (ascii(head, 4, 8) === 'ftyp') return brands[ascii(head, 8, 12)] ?? '.mp4';
	if (ascii(head, 0, 5) === '%PDF-') return '.pdf';
	if (ascii(head, 0, 4) === 'OggS') return '.ogg';
	if (ascii(head, 0, 4) === 'fLaC') return '.flac';
	if (ascii(head, 0, 3) === 'ID3') return '.mp3';
	if (first === 0xff && second !== undefined && (second & 0xf6) === 0xf0) return '.aac';
	if (first === 0xff && second !== undefined && (second & 0xe0) === 0xe0) return '.mp3';
	if (ascii(head, 0, 4) === '\x1aE\xdf\xa3') return '.webm';
	if (ascii(head, 0, 4) === 'PK\x03\x04') return '.zip';
	return null;
}

/** Leading bytes kept from a download to recognise its type. */
const headBytes = 16;

/**
 * Cached files are `<service>-<message id>-<random>[.ext]`: only safe
 * characters, so the path stays inside the cache directory, and not derivable
 * from the message alone. Partial files start with a dot and never match.
 */
function cacheStem(where: Service, id: string): string {
	return `${where}-${id}-`;
}

function findCached(directory: string, stem: string): string | null {
	const name = readdirSync(directory).find((entry) => entry.startsWith(stem));
	return name === undefined ? null : join(directory, name);
}

interface Downloaded {
	size: number;
	head: Uint8Array;
	/** The file name LINE keeps inside the E2EE payload, if any. */
	name?: string;
}

function tooLarge(limit: number): LineMcpError {
	return new LineMcpError('attachment_too_large', `The attachment is larger than ${limit} bytes`);
}

/** True when a response announces more than `limit` bytes. */
function announcesMore(response: Response, limit: number): boolean {
	const length = Number(response.headers.get('content-length'));
	return Number.isFinite(length) && length > limit;
}

/**
 * The byte limit and cancellation of the obs download in progress, if any.
 * LINEJS reads an E2EE download whole into a Blob and decrypts it in one piece
 * (base/obs/mod.ts:304-328, :459-488: an HMAC over the whole ciphertext), so
 * the only bound below that Blob is on the response: `boundObsFetch` refuses
 * it by Content-Length and errors its body once more than the limit arrived.
 */
const obsLimit = new AsyncLocalStorage<{
	limit: number;
	exceeded: boolean;
	signal: AbortSignal;
}>();
/** The HMAC-SHA256 trailer after the AES-CTR ciphertext of an E2EE file. */
const e2eeTrailerBytes = 32;
const boundClients = new WeakSet<BaseClient>();

/**
 * Wraps the session's guarded `fetch` once, so obs responses read inside
 * `obsLimit.run` stay within its limit. Requests outside it, and every
 * non-obs request (the key lookups of the same download), pass unchanged.
 */
function boundObsFetch(base: BaseClient): void {
	if (boundClients.has(base)) return;
	boundClients.add(base);
	const { fetch } = base;
	Object.assign(base, {
		fetch: (async (info, init) => {
			const bound = obsLimit.getStore();
			const url = typeof info === 'string' ? info : info instanceof URL ? info.href : info.url;
			if (!bound || !url.startsWith(base.obs.prefix)) return await fetch(info, init);
			const response = await fetch(info, { ...init, signal: bound.signal });
			if (!response.body) return response;
			if (announcesMore(response, bound.limit)) {
				bound.exceeded = true;
				await response.body.cancel();
				throw tooLarge(bound.limit);
			}
			let received = 0;
			const counted = response.body.pipeThrough(
				new TransformStream<Uint8Array, Uint8Array>({
					transform(chunk, controller) {
						received += chunk.byteLength;
						if (received > bound.limit) {
							bound.exceeded = true;
							controller.error(tooLarge(bound.limit));
							return;
						}
						controller.enqueue(chunk);
					}
				})
			);
			return new Response(counted, {
				status: response.status,
				statusText: response.statusText,
				headers: response.headers
			});
		}) satisfies typeof fetch
	});
}

/**
 * Plain media: the same request LINEJS's `downloadMessageData` sends
 * (base/obs/mod.ts:107-145), streamed to `partial` and stopped as soon as it
 * passes `limit`, so an oversized file never sits in memory or on disk.
 */
async function streamPlain(
	context: ToolContext,
	where: Service,
	message: Message,
	partial: string,
	limit: number,
	signal: AbortSignal
): Promise<Downloaded> {
	const { base } = context;
	const response = await base.fetch(
		base.obs.getMessageDataUrl(String(message.id), false, where === 'square'),
		{
			headers: {
				accept: 'application/json, text/plain, */*',
				'x-line-application': base.request.systemType,
				'x-Line-access': base.authToken ?? ''
			},
			signal
		}
	);
	if (!response.ok || !response.body) {
		await response.body?.cancel();
		// The body is left out: obs error pages embed signed URLs.
		throw new InternalError('ObsError', `Message data download failed: HTTP ${response.status}`, {
			status: response.status
		});
	}
	if (announcesMore(response, limit)) {
		await response.body.cancel();
		throw tooLarge(limit);
	}
	const file = await open(partial, 'w', 0o600);
	let received = 0;
	let head: Uint8Array = new Uint8Array(0);
	try {
		for await (const chunk of response.body) {
			received += chunk.byteLength;
			if (received > limit) throw tooLarge(limit);
			if (head.length < headBytes) head = Buffer.concat([head, chunk]).subarray(0, headBytes);
			await writeAll(file, chunk);
		}
	} finally {
		await file.close();
	}
	return { size: received, head };
}

/** `write` may persist only part of a chunk, for example near a size limit. */
export async function writeAll(file: Pick<FileHandle, 'write'>, chunk: Uint8Array): Promise<void> {
	for (let offset = 0; offset < chunk.byteLength;) {
		const { bytesWritten } = await file.write(chunk, offset, chunk.byteLength - offset);
		if (bytesWritten <= 0) throw new Error('Writing the attachment made no progress');
		offset += bytesWritten;
	}
}

/** E2EE media through LINEJS, bounded on the encrypted response; returns the decrypted size. */
async function downloadE2EE(
	context: ToolContext,
	message: Message,
	decryptState: string,
	partial: string,
	limit: number,
	signal: AbortSignal
): Promise<Downloaded> {
	const { base } = context;
	// The row only reaches `ok` once the exact key generations its envelope
	// names were verified (architecture, E2EE key boundaries); LINEJS then decrypts the file
	// key from the same envelope (base/obs/mod.ts:459-468).
	if (decryptState !== 'ok') {
		throw new LineMcpError('missing_key', 'The keys for this E2EE message are not available');
	}
	const verified = await decryptMessage(base, context.selfMid, message);
	if (verified.state !== 'ok') {
		throw new LineMcpError('missing_key', 'The keys for this E2EE message are not available');
	}
	boundObsFetch(base);
	// A file of exactly `limit` bytes arrives as `limit` plus the trailer.
	const bound = { limit: limit + e2eeTrailerBytes, exceeded: false, signal };
	let file: File | null;
	try {
		file = await obsLimit.run(bound, () => base.obs.downloadMediaByE2EE(message));
	} catch (error) {
		// Blob reading may wrap the stream's error; the flag says what happened.
		if (bound.exceeded) throw tooLarge(limit);
		throw error;
	}
	if (!file) throw new LineMcpError('no_attachment', 'This message has no attachment');
	if (file.size > limit) throw tooLarge(limit);
	const bytes = Buffer.from(await file.arrayBuffer());
	writeFileSync(partial, bytes, { mode: 0o600 });
	// LINEJS names the File "undefined" when the payload has no name.
	const name = text(verified.payload?.fileName) ?? undefined;
	return { size: file.size, head: bytes.subarray(0, headBytes), name };
}

/**
 * The file name inside an E2EE payload, which the plaintext metadata lacks.
 * Decrypting costs at most the read-only key lookups of `decryptMessage`, in
 * the pool. The name is optional, so any failure but a cancelled call leaves
 * it out.
 */
async function payloadFileName(
	context: ToolContext,
	message: Message,
	decryptState: string,
	signal: AbortSignal
): Promise<string | null> {
	// Only rows whose exact key generations were verified are decrypted.
	if (!message.chunks?.length || decryptState !== 'ok') return null;
	try {
		const result = await context.pool.run(
			() => decryptMessage(context.base, context.selfMid, message),
			signal
		);
		// A key lookup that answers after the caller went away still ends the call.
		signal.throwIfAborted();
		return result.state === 'ok' ? text(result.payload?.fileName) : null;
	} catch (error) {
		if (signal.aborted) throw error;
		context.log({ event: 'attachment_name_skipped', ...mapError(error, 'get_attachment') });
		return null;
	}
}

export const getAttachment = defineTool({
	name: 'get_attachment',
	description:
		'Attachment of an image, video, audio or file message: metadata, or with download true the file saved to a private cache and its local path. Refused for unsent messages.',
	upstream: true,
	input: z.object({
		service,
		chat_id: chatId,
		message_id: messageId,
		download: z.boolean().optional().describe('Download the file and return its local path')
	}),
	run: async (args, context, signal) => {
		const { db } = context;
		const found = findMessage(db, {
			service: args.service,
			chatId: args.chat_id,
			messageId: args.message_id
		});
		if (!found) throw new LineMcpError('not_found', 'No such message in this chat');
		// Unsend cleared the envelope (architecture, Tombstones); nothing of it is served.
		if (found.unsent) throw new LineMcpError('message_unsent', 'The message was unsent');
		const message = decodeEnvelope(readEnvelope(db, found.rowId)!);
		if (!mediaTypes.has(found.contentType ?? '')) {
			throw new LineMcpError('no_attachment', 'This message has no attachment');
		}
		const info = attachmentInfo(message);
		const described = describeMessage(db, context.selfMid, found);
		const named = async () => ({
			...info,
			file_name:
				info.file_name ?? (await payloadFileName(context, message, found.decryptState, signal))
		});
		if (!args.download) return { message: described, attachment: await named(), path: null };
		if (message.contentMetadata?.DOWNLOAD_URL && !message.contentMetadata?.OID) {
			throw new LineMcpError('no_attachment', 'The file is hosted outside LINE storage');
		}
		const limit = context.maxAttachmentBytes ?? maxAttachmentBytes;
		// FILE_SIZE comes from the sender, so this only spares a request; the
		// download itself enforces the limit on the bytes that arrive. For E2EE
		// media it counts the ciphertext with its HMAC trailer.
		const announced = limit + (info.e2ee ? e2eeTrailerBytes : 0);
		if (info.file_size !== null && info.file_size > announced) throw tooLarge(limit);
		await context.privacy.directory(context.attachments);
		const stem = cacheStem(args.service, found.messageId);
		const cached = findCached(context.attachments, stem);
		if (cached) {
			await context.privacy.file(cached);
			return { message: described, attachment: await named(), path: cached, cached: true };
		}
		// Written under a temporary name, so a reader never sees half a file.
		const random = randomBytes(12).toString('hex');
		const partial = join(context.attachments, `.${stem}${random}.partial`);
		try {
			const file = await context.pool.run(
				() =>
					info.e2ee
						? downloadE2EE(context, message, found.decryptState, partial, limit, signal)
						: streamPlain(context, args.service, message, partial, limit, signal),
				signal
			);
			const extension =
				plainExtension(info.file_name) ?? plainExtension(file.name) ?? sniffExtension(file.head);
			const path = join(context.attachments, `${stem}${random}${extension ?? ''}`);
			renameSync(partial, path);
			await context.privacy.file(path);
			return {
				message: described,
				attachment: {
					...info,
					file_name: info.file_name ?? file.name ?? null,
					file_size: file.size
				},
				path,
				cached: false
			};
		} finally {
			rmSync(partial, { force: true });
		}
	}
});

export const getAnnouncements = defineTool({
	name: 'get_announcements',
	description:
		'Pinned announcements of a group, room or OpenChat chat, asked from LINE. One-to-one chats have none.',
	upstream: true,
	input: z.object({ service, chat_id: chatId }),
	run: async (args, context, signal) => {
		const { base, db, pool } = context;
		const chat = findChat(db, args.service, args.chat_id);
		if (args.service === 'square') {
			const response = await pool.run(
				() =>
					base.square.getSquareChatAnnouncements({
						getSquareChatAnnouncementsRequest: { squareChatMid: args.chat_id }
					}),
				signal
			);
			return {
				chat,
				announcements: (response?.announcements ?? []).map((announcement) => {
					const contents = announcement.contents?.textMessageAnnouncementContents;
					const sender = text(contents?.senderSquareMemberMid) ?? text(announcement.creator);
					return {
						seq: integerId(announcement.announcementSeq),
						text: text(contents?.text),
						message_id: integerId(contents?.messageId),
						creator_id: sender,
						creator_name: personName(db, 'square', sender),
						created_at: renderTime(millis(announcement.createdAt))
					};
				})
			};
		}
		if (!/^[cr]/.test(args.chat_id)) {
			throw new LineMcpError('invalid_argument', 'Only groups and rooms have announcements');
		}
		const announcements = await pool.run(
			() => base.talk.getChatRoomAnnouncements({ chatRoomMid: args.chat_id }),
			signal
		);
		return {
			chat,
			announcements: (announcements ?? []).map((announcement) => {
				const creator = text(announcement.creatorMid);
				return {
					seq: integerId(announcement.announcementSeq),
					text: text(announcement.contents?.text),
					link: text(announcement.contents?.link),
					creator_id: creator,
					creator_name: personName(db, 'talk', creator),
					created_at: renderTime(millis(announcement.createdTime))
				};
			})
		};
	}
});

export const getProfile = defineTool({
	name: 'get_profile',
	description:
		'Profile from LINE: without id the connected LINE account; a Talk user MID; or with service square an OpenChat member ID (starting with p).',
	upstream: true,
	input: z.object({
		service: service.optional().describe('Default talk'),
		id: z
			.string()
			.regex(/^[a-z][0-9a-f]{32}$/)
			.optional()
			.describe('User MID (Talk) or member ID (Square); omit for the connected account')
	}),
	run: async (args, context, signal) => {
		const { base, db, pool, selfMid } = context;
		const where = args.service ?? 'talk';
		if (where === 'square') {
			if (!args.id) throw new LineMcpError('invalid_argument', 'Square needs a member id');
			const id = args.id;
			const response = await pool.run(
				() => base.square.getSquareMember({ squareMemberMid: id }),
				signal
			);
			const member = response?.squareMember;
			if (!member) throw new LineMcpError('not_found', 'LINE returned no member');
			return {
				profile: {
					service: 'square',
					id: text(member.squareMemberMid) ?? id,
					display_name: text(member.displayName),
					square_id: text(member.squareMid),
					membership: text(member.membershipState),
					role: text(member.role),
					archived_name: personName(db, 'square', id)
				}
			};
		}
		const id = args.id ?? selfMid;
		if (id === selfMid) {
			const profile = await pool.run(() => base.talk.getProfile(), signal);
			return {
				profile: {
					service: 'talk',
					id: text(profile?.mid) ?? id,
					self: true,
					display_name: text(profile?.displayName),
					status_message: text(profile?.statusMessage)
				}
			};
		}
		const response = await pool.run(() => base.talk.getContactsV2({ mids: [id] }), signal);
		const contact = response?.contacts?.[id]?.contact;
		if (!contact) throw new LineMcpError('not_found', 'LINE returned no contact');
		return {
			profile: {
				service: 'talk',
				id,
				self: false,
				display_name: text(contact.displayName),
				display_name_overridden: text(contact.displayNameOverridden),
				status_message: text(contact.statusMessage),
				archived_name: personName(db, 'talk', id)
			}
		};
	}
});

import { Buffer } from 'node:buffer';
import { createHash, randomUUID } from 'node:crypto';
import { open } from 'node:fs/promises';
import { basename, extname, isAbsolute } from 'node:path';
import type { BaseClient } from '@evex/linejs/base';
import { LINEStruct } from '@evex/linejs/thrift';
import type { Message } from '@evex/linejs-types';
import { z } from 'zod';
import { LineMcpError } from '../../errors.ts';
import { type SendingKeys, sendingKeys } from '../../keys.ts';
import { chunksDigest, type Payload, type Plan } from '../../outbox.ts';
import {
	chatId,
	defineTool,
	idempotencyKey,
	messageId,
	service,
	type ServedContext
} from '../tool.ts';
import { answeredId, type ChatKind, chatKind, pooled, targetMessage } from './mutation.ts';
import { maxAttachmentBytes, sniffExtension } from './upstream.ts';

/** LINE's own limit for one text message. */
const maxTextLength = 10_000;

interface Upload {
	bytes: Buffer;
	/** The name LINE shows, from the path. */
	name: string;
	/** Without the dot, as LINEJS puts it into MEDIA_CONTENT_INFO. */
	extension: string;
	kind: 'image' | 'gif' | 'file';
	mime: string;
	sha256: string;
}

const imageTypes: Record<string, { kind: Upload['kind']; mime: string }> = {
	'.jpg': { kind: 'image', mime: 'image/jpeg' },
	'.png': { kind: 'image', mime: 'image/png' },
	'.gif': { kind: 'gif', mime: 'image/gif' }
};

/**
 * Reads a local file to send. Its leading bytes decide whether it goes as an
 * image (JPEG, PNG, GIF) or as a file. Only regular files, up to the
 * attachment limit, are read.
 */
async function readUpload(path: string, limit: number): Promise<Upload> {
	if (!isAbsolute(path)) throw new LineMcpError('invalid_argument', 'file_path must be absolute');
	let bytes: Buffer;
	try {
		const file = await open(path, 'r');
		try {
			const stat = await file.stat();
			if (!stat.isFile()) throw new LineMcpError('file_error', 'file_path is not a regular file');
			if (stat.size > limit) {
				throw new LineMcpError('attachment_too_large', `The file is larger than ${limit} bytes`);
			}
			bytes = await file.readFile();
		} finally {
			await file.close();
		}
	} catch (error) {
		if (error instanceof LineMcpError) throw error;
		throw new LineMcpError('file_error', 'The file cannot be read');
	}
	if (bytes.length === 0) throw new LineMcpError('file_error', 'The file is empty');
	if (bytes.length > limit) {
		throw new LineMcpError('attachment_too_large', `The file is larger than ${limit} bytes`);
	}
	const sniffed = sniffExtension(bytes.subarray(0, 16));
	const image = sniffed ? imageTypes[sniffed] : undefined;
	const name = basename(path);
	const extension = (sniffed ?? extname(name)).replace(/^\./, '').toLowerCase() || 'bin';
	return {
		bytes,
		name,
		extension,
		kind: image?.kind ?? 'file',
		mime: image?.mime ?? 'application/octet-stream',
		sha256: createHash('sha256').update(bytes).digest('hex')
	};
}

interface Send {
	chatId: string;
	kind: ChatKind;
	threadId: string | null;
	replyTo: string | null;
	text: string | null;
	file: Upload | null;
}

type TalkFields = Pick<Message, 'contentType' | 'contentMetadata'> & {
	text?: string;
	chunks?: Buffer[];
};

/** Talk `sendMessage` as LINEJS builds it (base/service/talk/mod.ts:141-171), with our own sequence number. */
async function sendTalk(
	base: BaseClient,
	seq: number,
	to: string,
	fields: TalkFields,
	replyTo: string | null
) {
	const sent = await base.request.request<Message>(
		LINEStruct.sendMessage_args({
			seq,
			message: {
				to,
				createdTime: 0,
				deliveredTime: 0,
				hasContent: false,
				sessionId: 0,
				...fields,
				chunks: fields.chunks as never,
				...(replyTo
					? {
							relatedMessageId: replyTo,
							messageRelationType: 'REPLY',
							relatedMessageServiceCode: 'TALK'
						}
					: {})
			}
		}),
		'sendMessage',
		4,
		true,
		'/S4'
	);
	return { messageId: answeredId(sent?.id) };
}

/** An obs upload that must name the object it stored; it creates no message. */
async function upload(
	base: BaseClient,
	data: Blob,
	obsPath: string,
	params: Record<string, string>
): Promise<string> {
	const { objId } = await base.obs.uploadObjectForService({ data, oType: 'file', obsPath, params });
	if (!objId) throw new LineMcpError('upload_failed', 'LINE storage did not accept the upload');
	return objId;
}

/**
 * E2EE media as LINEJS's `uploadMediaByE2EE` sends it (base/obs/mod.ts:330-457):
 * the encrypted file (and for images its preview) is uploaded first, which
 * creates no message; only the `sendMessage` carrying its key is the action.
 */
async function planE2EEMedia(
	context: ServedContext,
	send: Send & { file: Upload },
	keys: SendingKeys
): Promise<Plan> {
	const { base, selfMid } = context;
	const { file } = send;
	if (send.kind !== 'user' && send.kind !== 'group') {
		throw new LineMcpError(
			'unsupported_action',
			'LINEJS sends E2EE media only to users and groups'
		);
	}
	// obs namespace, and the content type as a number (encryption) and a name (message).
	const [namespace, contentType, typeName] =
		file.kind === 'file' ? (['emf', 14, 'FILE'] as const) : (['emi', 1, 'IMAGE'] as const);
	const { keyMaterial, encryptedData } = await base.e2ee.encryptByKeyMaterial(file.bytes);
	const encrypted = new Blob([new Uint8Array(encryptedData)]);
	const params: Record<string, string> = {
		type: 'file',
		...(file.kind === 'gif' ? { cat: 'original' } : {})
	};
	const objectId = await upload(base, encrypted, `talk/${namespace}/reqid-${randomUUID()}`, params);
	if (file.kind !== 'file') {
		const preview = await upload(
			base,
			encrypted,
			`talk/${namespace}/${objectId}__ud-preview`,
			params
		);
		if (preview !== objectId) {
			throw new LineMcpError('upload_failed', 'LINE storage named another object for the preview');
		}
	}
	const chunks = base.e2ee.encryptE2EEMessageByData(
		keys.senderKeyId,
		keys.receiverKeyId,
		keys.keyData,
		keys.specVersion,
		{ keyMaterial, fileName: file.name },
		send.chatId,
		selfMid,
		contentType
	);
	const contentMetadata: Record<string, string> = {
		SID: namespace,
		OID: objectId,
		FILE_SIZE: String(encrypted.size),
		e2eeVersion: '2',
		...(file.kind === 'file'
			? {}
			: {
					MEDIA_CONTENT_INFO: JSON.stringify({
						category: 'original',
						fileSize: encrypted.size,
						extension: file.extension,
						animated: file.kind === 'gif'
					})
				})
	};
	const seq = await base.getReqseq('talk');
	return {
		requestSeq: seq,
		correlation: { e2ee: true, chunksSha256: chunksDigest(chunks) },
		dispatch: () =>
			sendTalk(
				base,
				seq,
				send.chatId,
				{ contentType: typeName, contentMetadata, chunks },
				send.replyTo
			)
	};
}

/**
 * Plain media the way LINEJS's `uploadObjTalk` sends it without an object ID
 * (base/obs/mod.ts:177-237): LINE creates the message from the upload itself,
 * so the upload is the action, and the message cannot carry a reply.
 */
async function planUpload(context: ServedContext, send: Send & { file: Upload }): Promise<Plan> {
	const { base } = context;
	const { file } = send;
	if (send.replyTo) {
		throw new LineMcpError(
			'unsupported_action',
			'Media LINE creates from an upload cannot be a reply; send the reply as text'
		);
	}
	const reqseq = await base.getReqseq('talk');
	const type = file.kind === 'file' ? 'file' : 'image';
	const params: Record<string, string> = {
		ver: '2.0',
		name: file.name,
		type,
		oid: 'reqseq',
		tomid: send.chatId,
		reqseq: String(reqseq),
		...(file.kind === 'file' ? {} : { cat: 'original' })
	};
	const data = new Blob([new Uint8Array(file.bytes)], { type: file.mime });
	const obsPath = `${send.kind === 'square' ? 'g2' : 'talk'}/m/reqseq`;
	return {
		requestSeq: reqseq,
		correlation: { e2ee: false },
		dispatch: async () => {
			const { objId } = await base.obs.uploadObjectForService({
				data,
				oType: type,
				obsPath,
				filename: file.name,
				params
			});
			if (!objId) throw new LineMcpError('upload_failed', 'LINE storage did not accept the upload');
			return { messageId: null, objectId: objId };
		}
	};
}

/**
 * Talk text or media, end-to-end encrypted whenever the chat is: a contact
 * whose key LINE negotiates, and every group or room. Only a contact without
 * E2EE support gets plain text, as LINEJS decides it.
 */
async function planTalk(context: ServedContext, send: Send): Promise<Plan> {
	const { base, selfMid } = context;
	const keys = await sendingKeys(base, selfMid, send.chatId, context.log);
	if (send.file) {
		const media = { ...send, file: send.file };
		return keys ? await planE2EEMedia(context, media, keys) : await planUpload(context, media);
	}
	const text = send.text!;
	let fields: TalkFields;
	let chunks: Buffer[] | undefined;
	if (keys) {
		chunks = base.e2ee.encryptE2EETextMessage(
			keys.senderKeyId,
			keys.receiverKeyId,
			keys.keyData,
			keys.specVersion,
			text,
			send.chatId,
			selfMid
		);
		fields = {
			contentType: 'NONE',
			contentMetadata: { e2eeVersion: '2', contentType: '0', e2eeMark: '2' },
			chunks
		};
	} else {
		fields = { contentType: 'NONE', contentMetadata: {}, text };
	}
	const seq = await base.getReqseq('talk');
	return {
		requestSeq: seq,
		correlation: chunks ? { e2ee: true, chunksSha256: chunksDigest(chunks) } : { e2ee: false },
		dispatch: () => sendTalk(base, seq, send.chatId, fields, send.replyTo)
	};
}

/**
 * OpenChat text: `sendMessage` in the chat, or `sendSquareThreadMessage` with
 * the thread's `threadMid` in a thread (base/service/square/mod.ts:147-186,
 * client/features/message/square.ts:502-533).
 */
async function planSquare(context: ServedContext, send: Send): Promise<Plan> {
	const { base } = context;
	if (send.file) return await planUpload(context, { ...send, file: send.file });
	const reqSeq = await base.getReqseq('sq');
	const reply = send.replyTo
		? {
				relatedMessageId: send.replyTo,
				relatedMessageServiceCode: 'SQUARE' as const,
				messageRelationType: 'REPLY' as const
			}
		: {};
	const text = send.text!;
	const threadMid = send.threadId;
	if (threadMid) {
		return {
			requestSeq: reqSeq,
			correlation: { e2ee: false },
			dispatch: async () => {
				const response = await base.square.sendSquareThreadMessage({
					request: {
						reqSeq,
						chatMid: send.chatId,
						threadMid,
						threadMessage: {
							message: {
								to: send.chatId,
								text,
								contentType: 'NONE',
								toType: 'SQUARE_THREAD',
								...reply
							}
						}
					}
				});
				return { messageId: answeredId(response?.createdThreadMessage?.message?.id) };
			}
		};
	}
	return {
		requestSeq: reqSeq,
		correlation: { e2ee: false },
		dispatch: async () => {
			const response = await base.request.request<{
				createdSquareMessage?: { message?: { id?: unknown } };
			}>(
				LINEStruct.SquareService_sendMessage_args({
					request: {
						reqSeq,
						squareChatMid: send.chatId,
						squareMessage: {
							squareMessageRevision: 4,
							message: { to: send.chatId, text, contentType: 0, contentMetadata: {}, ...reply }
						}
					}
				}),
				'sendMessage',
				4,
				true,
				'/SQ1'
			);
			return { messageId: answeredId(response?.createdSquareMessage?.message?.id) };
		}
	};
}

export const sendMessage = defineTool({
	name: 'send_message',
	description:
		'Sends a message from the connected LINE account: text, or a local image (JPEG, PNG, GIF) or file, optionally as a reply. Talk messages are end-to-end encrypted wherever the chat is. In OpenChat, a reply to a thread message goes into its thread; media cannot go into a thread or be a reply there. Needs an idempotency_key: a retry with the same key never sends twice. A result with state unknown means LINE may have sent it; check the newest messages of the chat with query before anything else.',
	upstream: true,
	mutating: true,
	input: z.object({
		service,
		chat_id: chatId,
		idempotency_key: idempotencyKey,
		text: z
			.string()
			.min(1)
			.max(maxTextLength)
			.optional()
			.describe('Message text; give either text or file_path'),
		file_path: z
			.string()
			.min(1)
			.max(4096)
			.optional()
			.describe(
				'Absolute path of a local image (JPEG, PNG, GIF) or other file to send instead of text'
			),
		reply_to: messageId.optional().describe('Reply to this message of the chat'),
		thread_id: z
			.string()
			.min(1)
			.max(100)
			.optional()
			.describe("Send into this OpenChat thread (a message's thread_id from query)")
	}),
	run: async (args, context, signal) => {
		const kind = chatKind(args.service, args.chat_id);
		if ((args.text === undefined) === (args.file_path === undefined)) {
			throw new LineMcpError('invalid_argument', 'Give exactly one of text or file_path');
		}
		if (args.thread_id !== undefined && kind !== 'square') {
			throw new LineMcpError('invalid_argument', 'Only OpenChat chats have threads');
		}
		let threadId = args.thread_id ?? null;
		if (args.reply_to) {
			const target = targetMessage(context, args.service, args.chat_id, args.reply_to);
			if (args.thread_id !== undefined && target.threadId !== args.thread_id) {
				throw new LineMcpError('invalid_argument', 'reply_to is not a message of this thread');
			}
			threadId = target.threadId;
		}
		const file = args.file_path
			? await readUpload(args.file_path, context.maxAttachmentBytes ?? maxAttachmentBytes)
			: null;
		// LINEJS has no upload into a thread; media meant for one is refused
		// rather than sent to the parent chat.
		if (file && threadId) {
			throw new LineMcpError('unsupported_action', 'Media cannot be sent into an OpenChat thread');
		}
		if (file && kind === 'square' && file.kind === 'file') {
			throw new LineMcpError(
				'unsupported_action',
				'LINEJS sends no files to OpenChat, only images'
			);
		}
		const send: Send = {
			chatId: args.chat_id,
			kind,
			threadId,
			replyTo: args.reply_to ?? null,
			text: args.text ?? null,
			file
		};
		const payload: Payload = {
			operation: 'send_message',
			service: args.service,
			chatId: args.chat_id,
			threadId,
			targetId: send.replyTo,
			text: send.text,
			reaction: null,
			attachmentSha256: file?.sha256 ?? null
		};
		return await context.outbox.execute(
			args.idempotency_key,
			payload,
			() => (kind === 'square' ? planSquare(context, send) : planTalk(context, send)),
			pooled(context, signal)
		);
	}
});
